    def test_godot_project_icon_uses_existing_source_asset(self):
        project = ROOT / "godot-mindustry" / "project.godot"
        asset_manifest = ROOT / "godot-mindustry" / "src" / "generated" / "asset_manifest.json"
        source = project.read_text(encoding="utf-8-sig")
        manifest = json.loads(asset_manifest.read_text(encoding="utf-8-sig"))

        icon_line = next(line for line in source.splitlines() if line.startswith("config/icon="))
        icon_path = icon_line.split("=", 1)[1].strip().strip('"')
        self.assertTrue(icon_path.startswith("res://assets/"))
        icon_file = ROOT / "godot-mindustry" / icon_path.removeprefix("res://")
        self.assertTrue(icon_file.exists(), f"Missing Godot project icon asset: {icon_path}")
        manifest_target = icon_path.removeprefix("res://assets/")
        self.assertIn(manifest_target, {entry["target"] for entry in manifest["assets"]})

    def test_manifest_requires_source_asset_paths(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            godot = root / "godot-mindustry"
            assets = godot / "assets"
            required = [
                "core/assets-raw/sprites/items/item-copper.png",
                "core/assets-raw/sprites/blocks/environment/ore-copper1.png",
                "core/assets-raw/sprites/blocks/environment/stone1.png",
                "core/assets-raw/sprites/blocks/drills/mechanical-drill.png",
                "core/assets-raw/sprites/blocks/distribution/conveyors/conveyor-0-0.png",
                "core/assets-raw/sprites/blocks/storage/core-shard.png",
            ]
            for rel in required:
                path = assets / rel
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(b"asset")
            seed = godot / "src" / "generated" / "playable_content.json"
            seed.parent.mkdir(parents=True, exist_ok=True)
            seed.write_text('{"tile_size": 32}\n', encoding="utf-8")

            manifest = build_playable_manifest(assets, godot_root=godot)

        self.assertEqual(manifest["item"]["id"], "copper")
        self.assertEqual(set(manifest["blocks"].keys()), {"core_shard", "mechanical_drill", "conveyor", "ore_copper", "stone_floor"})
        for entry in [manifest["item"], *manifest["blocks"].values()]:
            self.assertTrue(entry["texture"].startswith("res://assets/"))

