    def test_port_game_exposes_source_power_graph_power_needed_state_for_mcp(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourcePowerGraphState.gd"
        consume_power = ROOT / "godot-mindustry" / "src" / "game" / "SourceConsumePowerState.gd"
        source = port_game.read_text(encoding="utf-8")
        helper_source = helper.read_text(encoding="utf-8")
        consume_power_source = consume_power.read_text(encoding="utf-8")
        requested_power_body = self._method_body(source, "func source_consume_power_requested_power_state(buffered: bool, usage: float, capacity: float, power_status: float, should_consume: bool) -> Dictionary:")

        self.assertIn("func source_consume_power_requested_power_state(buffered: bool, usage: float, capacity: float, power_status: float, should_consume: bool) -> Dictionary:", source)
        self.assertIn("static func requested_power_state(buffered: bool, usage: float, capacity: float, power_status: float, should_consume: bool) -> Dictionary:", consume_power_source)
        self.assertIn("\treturn SourceConsumePowerState.requested_power_state(buffered, usage, capacity, power_status, should_consume)", requested_power_body)
        self.assertIn('"source_owner": "PortGame.source_consume_power_requested_power_state"', consume_power_source)
        self.assertIn('"buffered_expr": "(1f - entity.power.status) * capacity"', consume_power_source)
        self.assertIn('"unbuffered_expr": "usage * (entity.shouldConsume() ? 1f : 0f)"', consume_power_source)
        self.assertNotIn('"buffered_expr": "(1f - entity.power.status) * capacity"', requested_power_body)
        self.assertNotIn('"unbuffered_expr": "usage * (entity.shouldConsume() ? 1f : 0f)"', requested_power_body)
        self.assertIn("static func power_needed_state(consumers: Array, requested_power_state: Callable) -> Dictionary:", helper_source)
        self.assertIn("func source_power_graph_power_needed_state(consumers: Array) -> Dictionary:", source)
        self.assertIn('return SourcePowerGraphState.power_needed_state(consumers, Callable(self, "source_consume_power_requested_power_state"))', source)
        self.assertIn('"method": "public float getPowerNeeded(){"', helper_source)
        self.assertIn('"add_expr": "powerNeeded += consumePower.requestedPower(consumer) * consumer.delta();"', helper_source)
        self.assertIn('if bool(consumer.get("shouldConsumePower", false)):', helper_source)
        self.assertIn('"placed_power_needed": game.call("placed_power_needed_state")', self._runtime_summary_source())

