    def test_source_item_transport_runtime_state_keeps_sprite_motion_ssot(self):
        source = self._port_game_item_transport_runtime_source()

        self.assertIn("static func bootstrap_state(path_points_input: Array[Vector2], sprite_count: int, sprite_key: String) -> Dictionary:", source)
