        runtime_source = runtime_state.read_text(encoding="utf-8")

        self.assertIn('const SourceTurretPropertyState := preload("res://src/game/SourceTurretPropertyState.gd")', runtime_source)
        self.assertIn("static func turret_reload_seconds(turret, reload_key: String, reload_default: float, tick_rate: float) -> float:", runtime_source)
        self.assertIn("static func turret_range(turret, range_key: String, range_default: float) -> float:", runtime_source)
        self.assertIn("static func turret_shoot_y(turret, shoot_y_key: String, shoot_y_default: float) -> float:", runtime_source)
        self.assertIn("static func turret_inaccuracy(turret, inaccuracy_key: String, inaccuracy_default: float) -> float:", runtime_source)
        self.assertIn("static func turret_rotate_speed(turret, rotate_speed_key: String, rotate_speed_default: float) -> float:", runtime_source)
        self.assertIn("static func turret_shoot_cone(turret, shoot_cone_key: String, shoot_cone_default: float) -> float:", runtime_source)
        self.assertIn("static func turret_recoil(turret, recoil_key: String, recoil_default: float) -> float:", runtime_source)
        self.assertIn("static func turret_recoils(turret, recoils_key: String, recoils_default: int) -> int:", runtime_source)
        self.assertIn("static func turret_recoil_time(turret, recoil_time_key: String, recoil_time_default: float, reload_key: String, reload_default: float, tick_rate: float) -> float:", runtime_source)
        self.assertIn("static func turret_shoot_pattern(turret, shoot_pattern_key: String) -> Dictionary:", runtime_source)

        expected_delegates = {
            "func source_turret_reload_seconds(turret) -> float:": "return SourceTurretRuntimeState.turret_reload_seconds(turret, SOURCE_TURRET_RELOAD_KEY, SOURCE_TURRET_RELOAD_DEFAULT, SOURCE_TICK_RATE)",
            "func source_turret_range(turret) -> float:": "return SourceTurretRuntimeState.turret_range(turret, SOURCE_TURRET_RANGE_KEY, SOURCE_TURRET_RANGE_DEFAULT)",
            "func source_turret_shoot_y(turret) -> float:": "return SourceTurretRuntimeState.turret_shoot_y(turret, SOURCE_TURRET_SHOOT_Y_KEY, SOURCE_TURRET_SHOOT_Y_DEFAULT)",
            "func source_turret_inaccuracy(turret) -> float:": "return SourceTurretRuntimeState.turret_inaccuracy(turret, SOURCE_TURRET_INACCURACY_KEY, SOURCE_TURRET_INACCURACY_DEFAULT)",
            "func source_turret_rotate_speed(turret) -> float:": "return SourceTurretRuntimeState.turret_rotate_speed(turret, SOURCE_TURRET_ROTATE_SPEED_KEY, SOURCE_TURRET_ROTATE_SPEED_DEFAULT)",
            "func source_turret_shoot_cone(turret) -> float:": "return SourceTurretRuntimeState.turret_shoot_cone(turret, SOURCE_TURRET_SHOOT_CONE_KEY, SOURCE_TURRET_SHOOT_CONE_DEFAULT)",
            "func source_turret_recoil(turret) -> float:": "return SourceTurretRuntimeState.turret_recoil(turret, SOURCE_TURRET_RECOIL_KEY, SOURCE_TURRET_RECOIL_DEFAULT)",
            "func source_turret_recoils(turret) -> int:": "return SourceTurretRuntimeState.turret_recoils(turret, SOURCE_TURRET_RECOILS_KEY, SOURCE_TURRET_RECOILS_DEFAULT)",
            "func source_turret_recoil_time(turret) -> float:": "return SourceTurretRuntimeState.turret_recoil_time(turret, SOURCE_TURRET_RECOIL_TIME_KEY, SOURCE_TURRET_RECOIL_TIME_DEFAULT, SOURCE_TURRET_RELOAD_KEY, SOURCE_TURRET_RELOAD_DEFAULT, SOURCE_TICK_RATE)",
            "func source_turret_shoot_pattern(turret) -> Dictionary:": "return SourceTurretRuntimeState.turret_shoot_pattern(turret, SOURCE_TURRET_SHOOT_PATTERN_KEY)",
        }
        for signature, delegate in expected_delegates.items():
            with self.subTest(signature=signature):
                method_body = self._method_body(source, signature)
                self.assertIn(delegate, method_body)
                self.assertNotIn("SourceTurretPropertyState.", method_body)
                self.assertNotIn("var turret_properties := _turret_properties(turret)", method_body)

