        function_body = source.split("func source_dump_accumulate_attempt_state(current_accum: float, source_delta: float) -> Dictionary:", 1)[1].split("\nfunc ", 1)[0]

        self.assertTrue(helper.exists(), "SourceBuildingItemDumpState.gd helper must own Building dump accumulator state")
        self.assertIn("var building_dump_accum := 0.0", source)
        self.assertIn('const SOURCE_DUMP_ACCUMULATE_ATTEMPT_FIELD := "private transient float dumpAccum;"', source)
        self.assertIn('const SOURCE_DUMP_ACCUMULATE_ATTEMPT_ADD_DELTA := "dumpAccum += delta();"', source)
        self.assertIn('const SOURCE_DUMP_ACCUMULATE_ATTEMPT_WHILE_GATE := "while(dumpAccum >= 1f){"', source)
        self.assertIn('const SOURCE_DUMP_ACCUMULATE_ATTEMPT_DUMP_CALL := "res |= dump(item);"', source)
        self.assertIn('const SOURCE_DUMP_ACCUMULATE_ATTEMPT_SUBTRACT_ONE := "dumpAccum -=1f;"', source)
        self.assertIn("func source_dump_accumulate_attempt_state(current_accum: float, source_delta: float) -> Dictionary:", source)
        self.assertIn("return SourceBuildingItemDumpState.dump_accumulate_state(current_accum, source_delta)", source)
        self.assertIn("static func dump_accumulate_state(current_accum: float, source_delta: float) -> Dictionary:", helper_source)
        self.assertIn("var next_accum := current_accum + source_delta", helper_source)
        self.assertIn("var dump_attempts := 0", helper_source)
        self.assertIn("while next_accum >= 1.0:", helper_source)
        self.assertIn("dump_attempts += 1", helper_source)
        self.assertIn("next_accum -= 1.0", helper_source)
        self.assertIn('return {"dump_attempts": dump_attempts, "dump_accum": next_accum}', helper_source)
        self.assertNotIn("var next_accum := current_accum + source_delta", function_body)
        self.assertNotIn('return {"dump_attempts": dump_attempts, "dump_accum": next_accum}', function_body)
        self.assertIn("func step_building_dump_accum(source_delta: float) -> Dictionary:", source)
        self.assertIn("building_dump_accum = float(state[\"dump_accum\"])", source)
        self.assertIn('"building_dump_accum": float(game.get("building_dump_accum"))', summary_source)

