        self.assertTrue(helper.exists(), "SourceBuildingDamageState.gd helper must own Building collision damage math")
        self.assertIn("class_name SourceDamageDefaults", damage_source)
        self.assertIn("const MIN_ARMOR_DAMAGE := 0.1", damage_source)
        self.assertIn("const SourceDamageDefaults := preload(\"res://src/game/SourceDamageDefaults.gd\")", source)
        self.assertIn("const SOURCE_DAMAGE_MIN_ARMOR_DAMAGE := SourceDamageDefaults.MIN_ARMOR_DAMAGE", source)
        self.assertIn("func source_building_collision_damage_state(current_health: float, bullet_building_damage: float, block_armor: float, bullet_pierce_armor: bool, bullet_armor_multiplier: float, bullet_block_armor_multiplier: float) -> Dictionary:", source)
        self.assertIn("return SourceBuildingDamageState.collision_damage_state(current_health, bullet_building_damage, block_armor, bullet_pierce_armor, bullet_armor_multiplier, bullet_block_armor_multiplier, SOURCE_DAMAGE_MIN_ARMOR_DAMAGE)", source)
        self.assertIn("static func collision_damage_state(current_health: float, bullet_building_damage: float, block_armor: float, bullet_pierce_armor: bool, bullet_armor_multiplier: float, bullet_block_armor_multiplier: float, source_damage_min_armor_damage: float) -> Dictionary:", helper_source)
        self.assertIn("var armor := block_armor * bullet_armor_multiplier * bullet_block_armor_multiplier", helper_source)
        self.assertIn("if not bullet_pierce_armor:", helper_source)
        self.assertIn("damage = max(damage - armor, source_damage_min_armor_damage * damage)", helper_source)
        self.assertNotIn("damage = max(damage - armor, 0.1 * damage)", source)
        self.assertIn('"was_dead": current_health <= 0.0', helper_source)
        self.assertIn('"removed": true', helper_source)
