    def test_port_game_exposes_source_unit_wobble_state(self):
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitUpdateState.gd"
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        unit_defaults = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitDefaults.gd"
        source = port_game.read_text(encoding="utf-8")
        helper_source = helper.read_text(encoding="utf-8") if helper.exists() else ""
        unit_source = unit_defaults.read_text(encoding="utf-8")
        function_body = source.split("func source_unit_wobble_state(current_x: float, current_y: float, source_time: float, source_delta: float, elevation_value: float, unit_id: int) -> Dictionary:", 1)[1].split("\nfunc ", 1)[0]

        self.assertIn("const SOURCE_ARC_SIN_BITS := SourceMathDefaults.ARC_SIN_BITS", source)
        self.assertIn("const SOURCE_ARC_SIN_MASK := SourceMathDefaults.ARC_SIN_MASK", source)
        self.assertIn("func source_arc_mathf_sin_lookup(radians: float) -> float:", source)
        self.assertIn("return sin((float(index) + 0.5) / float(SOURCE_ARC_SIN_COUNT) * SOURCE_ARC_RAD_FULL)", source)
        self.assertIn("func source_arc_mathf_sin_scaled(radians: float, scl: float, mag: float) -> float:", source)
        self.assertIn("return source_arc_mathf_sin_lookup(radians / scl) * mag", source)
        self.assertIn("func source_arc_mathf_cos_scaled(radians: float, scl: float, mag: float) -> float:", source)
        self.assertIn("return source_arc_mathf_cos_lookup(radians / scl) * mag", source)
        self.assertIn("func source_unit_wobble_state(current_x: float, current_y: float, source_time: float, source_delta: float, elevation_value: float, unit_id: int) -> Dictionary:", source)
        self.assertIn("const WOBBLE_SIN_SCL := 25.0", unit_source)
        self.assertIn("const WOBBLE_MAG := 0.05", unit_source)
        self.assertIn("const SOURCE_UNIT_WOBBLE_SIN_SCL := SourceUnitDefaults.WOBBLE_SIN_SCL", source)
        self.assertIn("const SOURCE_UNIT_WOBBLE_MAG := SourceUnitDefaults.WOBBLE_MAG", source)
        self.assertIn("const SOURCE_UNIT_WOBBLE_SIN_SCL := SourceUnitDefaults.WOBBLE_SIN_SCL", helper_source)
        self.assertIn("const SOURCE_UNIT_WOBBLE_MAG := SourceUnitDefaults.WOBBLE_MAG", helper_source)
        self.assertIn('return SourceUnitUpdateState.wobble_state(current_x, current_y, source_time, source_delta, elevation_value, unit_id, Callable(self, "source_arc_mathf_sin_scaled"), Callable(self, "source_arc_mathf_cos_scaled"))', source)
        self.assertIn("static func wobble_state(current_x: float, current_y: float, source_time: float, source_delta: float, elevation_value: float, unit_id: int, sin_scaled: Callable, cos_scaled: Callable) -> Dictionary:", helper_source)
        self.assertIn("var wobble_input := source_time + float(unit_id % 10) * 12.0", helper_source)
        self.assertIn("var dx := float(sin_scaled.call(wobble_input, SOURCE_UNIT_WOBBLE_SIN_SCL, SOURCE_UNIT_WOBBLE_MAG)) * source_delta * elevation_value", helper_source)
        self.assertIn("var dy := float(cos_scaled.call(wobble_input, SOURCE_UNIT_WOBBLE_SIN_SCL, SOURCE_UNIT_WOBBLE_MAG)) * source_delta * elevation_value", helper_source)
        self.assertNotIn("var wobble_input := source_time + float(unit_id % 10) * 12.0", function_body)
        self.assertNotIn("var dx := source_arc_mathf_sin_scaled(wobble_input, 25.0, 0.05) * source_delta * elevation_value", source)

