    def test_port_game_exposes_source_unit_update_drowning_state(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        helper = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitUpdateState.gd"
        unit_defaults = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitDefaults.gd"
        source = port_game.read_text(encoding="utf-8")
        self.assertTrue(helper.exists())
        helper_source = helper.read_text(encoding="utf-8")
        unit_source = unit_defaults.read_text(encoding="utf-8")

        self.assertIn("func source_unit_update_drowning_state(floor_exists: bool, floor_is_liquid: bool, floor_drown_time: float, can_drown_value: bool, current_drown_time: float, source_delta: float, hit_size: float, type_drown_time_multiplier: float, chance_delta_result: bool, net_client: bool) -> Dictionary:", source)
        self.assertIn("return SourceUnitUpdateState.drowning_state(floor_exists, floor_is_liquid, floor_drown_time, can_drown_value, current_drown_time, source_delta, hit_size, type_drown_time_multiplier, chance_delta_result, net_client)", source)
        self.assertIn("static func drowning_state(floor_exists: bool, floor_is_liquid: bool, floor_drown_time: float, can_drown_value: bool, current_drown_time: float, source_delta: float, hit_size: float, type_drown_time_multiplier: float, chance_delta_result: bool, net_client: bool) -> Dictionary:", helper_source)
        self.assertIn("const DROWN_HIT_SIZE_DIVISOR := 8.0", unit_source)
        self.assertIn("const DROWN_UPDATE_EFFECT_CHANCE := 0.05", unit_source)
        self.assertIn("const DROWN_KILL_THRESHOLD := 0.999", unit_source)
        self.assertIn("const DROWN_DRY_DECAY_DIVISOR := 50.0", unit_source)
        self.assertIn("const SOURCE_UNIT_DROWN_HIT_SIZE_DIVISOR := SourceUnitDefaults.DROWN_HIT_SIZE_DIVISOR", helper_source)
        self.assertIn("const SOURCE_UNIT_DROWN_UPDATE_EFFECT_CHANCE := SourceUnitDefaults.DROWN_UPDATE_EFFECT_CHANCE", helper_source)
        self.assertIn("const SOURCE_UNIT_DROWN_KILL_THRESHOLD := SourceUnitDefaults.DROWN_KILL_THRESHOLD", helper_source)
        self.assertIn("const SOURCE_UNIT_DROWN_DRY_DECAY_DIVISOR := SourceUnitDefaults.DROWN_DRY_DECAY_DIVISOR", helper_source)
        self.assertIn("var can_drown_on_floor := floor_exists and floor_is_liquid and floor_drown_time > 0.0 and can_drown_value", helper_source)
