    def test_port_game_delegates_source_ability_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        source = port_game.read_text(encoding="utf-8")

        self.assertIn('const SourceAbilityState := preload("res://src/game/SourceAbilityState.gd")', source)
        delegates = {
            "func source_ability_update_state(unit: Variant) -> Dictionary:": "return SourceAbilityState.update_state(unit)",
            "func source_ability_draw_state(unit: Variant) -> Dictionary:": "return SourceAbilityState.draw_state(unit)",
            "func source_ability_death_state(unit: Variant) -> Dictionary:": "return SourceAbilityState.death_state(unit)",
            "func source_ability_created_state(unit: Variant) -> Dictionary:": "return SourceAbilityState.created_state(unit)",
            "func source_ability_init_state(type_value: Variant) -> Dictionary:": "return SourceAbilityState.init_state(type_value)",
            "func source_ability_display_bars_state(unit: Variant, bars: Variant) -> Dictionary:": "return SourceAbilityState.display_bars_state(unit, bars)",
            "func source_ability_display_state(table_state: Variant, localized_value: String) -> Dictionary:": "return SourceAbilityState.display_state(table_state, localized_value)",
            "func source_ability_add_stats_state(table_state: Variant, get_bundle_value: String, bundle_has_description: bool, bundle_description: String) -> Dictionary:": "return SourceAbilityState.add_stats_state(table_state, get_bundle_value, bundle_has_description, bundle_description)",
            "func source_ability_ability_stat_state(stat_value: String, values: Array, formatted_value: String) -> Dictionary:": "return SourceAbilityState.ability_stat_state(stat_value, values, formatted_value)",
            "func source_ability_copy_state(clone_supported: bool, clone_value: Variant, exception_value: Variant) -> Dictionary:": "return SourceAbilityState.copy_state(clone_supported, clone_value, exception_value)",
            "func source_ability_localized_state(get_bundle_value: String, bundle_value: String) -> Dictionary:": "return SourceAbilityState.localized_state(get_bundle_value, bundle_value)",
            "func source_ability_get_bundle_state(class_simple_name: String, is_anonymous_class: bool, superclass_simple_name: String) -> Dictionary:": "return SourceAbilityState.get_bundle_state(class_simple_name, is_anonymous_class, superclass_simple_name)",
        }
        for signature, expected_delegate in delegates.items():
            with self.subTest(signature=signature):
                body = self._method_body(source, signature)
                self.assertIn(expected_delegate, body)
                self.assertNotIn('"source": "core/src/mindustry/entities/abilities/Ability.java"', body)

