    def test_port_game_delegates_source_block_query_state_to_module(self):
        source = self._port_game_block_query_source()

        self.assertIn('const SourceBlockQueryState := preload("res://src/game/SourceBlockQueryState.gd")', source)
        delegates = {
            "func source_block_outputs_items_state(has_items: bool) -> Dictionary:": "return SourceBlockQueryState.outputs_items_state(has_items)",
            "func source_block_can_place_on_state(tile: Variant, team: Variant, rotation_value: int) -> Dictionary:": "return SourceBlockQueryState.can_place_on_state(tile, team, rotation_value)",
            "func source_block_can_break_state(tile: Variant) -> Dictionary:": "return SourceBlockQueryState.can_break_state(tile)",
            "func source_block_rotated_output_state(rotate_value: bool, x_value: int, y_value: int) -> Dictionary:": "return SourceBlockQueryState.rotated_output_state(rotate_value, x_value, y_value)",
            "func source_block_rotated_output_tile_state(rotate_value: bool, from_x: int, from_y: int, destination: Variant) -> Dictionary:": "return SourceBlockQueryState.rotated_output_tile_state(rotate_value, from_x, from_y, destination)",
            "func source_block_synthetic_state(update_value: bool, destructible_value: bool) -> Dictionary:": "return SourceBlockQueryState.synthetic_state(update_value, destructible_value)",
            "func source_block_check_force_dark_state(force_dark_value: bool, tile: Variant) -> Dictionary:": "return SourceBlockQueryState.check_force_dark_state(force_dark_value, tile)",
            "func source_block_is_darkened_state(solid_value: bool, update_value: bool, destructible_value: bool, fills_tile_value: bool, force_dark_value: bool, tile: Variant) -> Dictionary:": "return SourceBlockQueryState.is_darkened_state(solid_value, update_value, destructible_value, fills_tile_value, force_dark_value, tile)",
            "func source_block_consumes_item_state(item_filter: Array, item_id: int, item: Variant) -> Dictionary:": "return SourceBlockQueryState.consumes_item_state(item_filter, item_id, item)",
            "func source_block_consumes_liquid_state(liquid_filter: Array, liquid_id: int, liq: Variant) -> Dictionary:": "return SourceBlockQueryState.consumes_liquid_state(liquid_filter, liquid_id, liq)",
            "func source_block_has_building_state(destructible_value: bool, update_value: bool) -> Dictionary:": "return SourceBlockQueryState.has_building_state(destructible_value, update_value)",
            "func source_block_is_multiblock_state(size_value: int) -> Dictionary:": "return SourceBlockQueryState.is_multiblock_state(size_value)",
            "func source_block_is_air_state(id_value: int) -> Dictionary:": "return SourceBlockQueryState.is_air_state(id_value)",
            "func source_block_can_be_built_state(build_visibility_value: String) -> Dictionary:": "return SourceBlockQueryState.can_be_built_state(build_visibility_value)",
            "func source_block_is_static_state(cache_layer_value: String) -> Dictionary:": "return SourceBlockQueryState.is_static_state(cache_layer_value)",
            "func source_block_has_consumer_state(consume_builder_contains: bool, cons: Variant) -> Dictionary:": "return SourceBlockQueryState.has_consumer_state(consume_builder_contains, cons)",
            "func source_block_remove_consumer_state(consumers_length: int, cons: Variant) -> Dictionary:": "return SourceBlockQueryState.remove_consumer_state(consumers_length, cons)",
            "func source_block_remove_consumers_state(consume_builder_contains_power_after_remove: bool, b: Variant) -> Dictionary:": "return SourceBlockQueryState.remove_consumers_state(consume_builder_contains_power_after_remove, b)",
        }
        for signature, expected_delegate in delegates.items():
            with self.subTest(signature=signature):
                body = self._method_body(source, signature)
                self.assertIn(expected_delegate, body)

