        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockConsumeState.gd"
        source = port_game.read_text(encoding="utf-8")

        self.assertTrue(module.exists(), "SourceBlockConsumeState.gd must own Block consume source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const SourceBlockConsumeState := preload("res://src/game/SourceBlockConsumeState.gd")', source)

        delegations = {
            "func source_block_consume_liquid_state(liquid: Variant, amount: float) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_liquid_state(liquid, amount)",
            "func source_block_consume_liquids_state(stacks: Variant) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_liquids_state(stacks)",
            "func source_block_consume_power_state(power_per_tick: float) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_power_state(power_per_tick)",
            "func source_block_consume_power_cond_state(usage: float, cons: Variant) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_power_cond_state(usage, cons)",
            "func source_block_consume_power_dynamic_state(usage: Variant) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_power_dynamic_state(usage)",
            "func source_block_consume_power_dynamic_displayed_state(displayed: float, usage: Variant) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_power_dynamic_displayed_state(displayed, usage)",
            "func source_block_consume_power_buffered_state(power_capacity: float) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_power_buffered_state(power_capacity)",
            "func source_block_consume_item_single_state(item: Variant) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_item_single_state(item)",
            "func source_block_consume_item_amount_state(item: Variant, amount: int) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_item_amount_state(item, amount)",
            "func source_block_consume_items_varargs_state(items: Array) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_items_varargs_state(items)",
            "func source_block_consume_coolant_single_state(amount: float) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_coolant_single_state(amount)",
            "func source_block_consume_coolant_filtered_state(amount: float, allow_liquid: bool, allow_gas: bool) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_coolant_filtered_state(amount, allow_liquid, allow_gas)",
            "func source_block_consume_generic_state(consume: Variant, consume_is_power: bool, consume_builder_before: Array, consume_builder_without_power: Array, cons_power_before: Variant) -> Dictionary:": "\treturn SourceBlockConsumeState.consume_generic_state(consume, consume_is_power, consume_builder_before, consume_builder_without_power, cons_power_before)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/Block.java"', method_body)

        for method_name in (
            "consume_liquid_state",
            "consume_liquids_state",
            "consume_power_state",
            "consume_power_cond_state",
            "consume_power_dynamic_state",
            "consume_power_dynamic_displayed_state",
            "consume_power_buffered_state",
            "consume_item_single_state",
            "consume_item_amount_state",
            "consume_items_varargs_state",
            "consume_coolant_single_state",
            "consume_coolant_filtered_state",
            "consume_generic_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "PortGame.source_block_consume_liquid_state",
            "PortGame.source_block_consume_liquids_state",
            "PortGame.source_block_consume_power_state",
            "PortGame.source_block_consume_power_cond_state",
            "PortGame.source_block_consume_power_dynamic_state",
            "PortGame.source_block_consume_power_dynamic_displayed_state",
            "PortGame.source_block_consume_power_buffered_state",
            "PortGame.source_block_consume_item_single_state",
            "PortGame.source_block_consume_item_amount_state",
            "PortGame.source_block_consume_items_varargs_state",
            "PortGame.source_block_consume_coolant_single_state",
            "PortGame.source_block_consume_coolant_filtered_state",
            "PortGame.source_block_consume_generic_state",
        ):
            self.assertIn('"source_owner": "' + source_owner + '"', module_source)

