    def test_port_game_delegates_block_requirements_source_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockRequirementsState.gd"
        source = port_game.read_text(encoding="utf-8")

        self.assertTrue(module.exists(), "SourceBlockRequirementsState.gd must own Block setupRequirements/requirements source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const SourceBlockRequirementsState := preload("res://src/game/SourceBlockRequirementsState.gd")', source)

        delegations = {
            "func source_block_setup_requirements_simple_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn SourceBlockRequirementsState.setup_requirements_simple_state(cat, stacks)",
            "func source_block_setup_requirements_visible_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn SourceBlockRequirementsState.setup_requirements_visible_state(cat, build_visibility, stacks)",
            "func source_block_requirements_unlocked_state(cat: Variant, stacks: Variant, unlocked: bool) -> Dictionary:": "\treturn SourceBlockRequirementsState.requirements_unlocked_state(cat, stacks, unlocked)",
            "func source_block_requirements_simple_state(cat: Variant, stacks: Variant) -> Dictionary:": "\treturn SourceBlockRequirementsState.requirements_simple_state(cat, stacks)",
            "func source_block_requirements_visible_state(cat: Variant, build_visibility: Variant, stacks: Variant) -> Dictionary:": "\treturn SourceBlockRequirementsState.requirements_visible_state(cat, build_visibility, stacks)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/Block.java"', method_body)

        for method_name in (
            "setup_requirements_simple_state",
            "setup_requirements_visible_state",
            "requirements_unlocked_state",
            "requirements_simple_state",
            "requirements_visible_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "PortGame.source_block_setup_requirements_simple_state",
            "PortGame.source_block_setup_requirements_visible_state",
            "PortGame.source_block_requirements_unlocked_state",
            "PortGame.source_block_requirements_simple_state",
            "PortGame.source_block_requirements_visible_state",
        ):
            self.assertIn('"source_owner": "' + source_owner + '"', module_source)

