    def test_port_game_delegates_block_research_requirements_source_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceBlockResearchRequirementsState.gd"
        source = port_game.read_text(encoding="utf-8")

        self.assertTrue(module.exists(), "SourceBlockResearchRequirementsState.gd must own Block researchRequirements source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const SourceBlockResearchRequirementsState := preload("res://src/game/SourceBlockResearchRequirementsState.gd")', source)

        delegations = {
            "func source_block_research_requirements_research_cost_state(research_cost: Variant) -> Dictionary:": "\treturn SourceBlockResearchRequirementsState.research_cost_state(research_cost)",
            "func source_block_research_requirements_empty_state(research_cost: Variant, research_cost_multiplier: float) -> Dictionary:": "\treturn SourceBlockResearchRequirementsState.empty_state(research_cost, research_cost_multiplier)",
            "func source_block_research_requirements_loop_shape_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array) -> Dictionary:": "\treturn SourceBlockResearchRequirementsState.loop_shape_state(research_cost, research_cost_multiplier, requirements)",
            "func source_block_research_requirements_quantity_formula_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary) -> Dictionary:": "\treturn SourceBlockResearchRequirementsState.quantity_formula_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_BASE_QUANTITY, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_AMOUNT_EXPONENT, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_AMOUNT_SCALE, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_ROUND_STEP)",
            "func source_block_research_requirements_round_amount_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary) -> Dictionary:": "\treturn SourceBlockResearchRequirementsState.round_amount_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_BASE_QUANTITY, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_AMOUNT_EXPONENT, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_AMOUNT_SCALE, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_ROUND_STEP)",
            "func source_block_research_requirements_output_fill_state(research_cost: Variant, research_cost_multiplier: float, requirements: Array, research_cost_multipliers: Dictionary) -> Dictionary:": "\treturn SourceBlockResearchRequirementsState.output_fill_state(research_cost, research_cost_multiplier, requirements, research_cost_multipliers, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_BASE_QUANTITY, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_AMOUNT_EXPONENT, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_AMOUNT_SCALE, SOURCE_BLOCK_RESEARCH_REQUIREMENTS_ROUND_STEP)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/Block.java"', method_body)

        for method_name in (
            "research_cost_state",
            "empty_state",
            "loop_shape_state",
            "quantity_formula_state",
            "round_amount_state",
            "output_fill_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "PortGame.source_block_research_requirements_research_cost_state",
            "PortGame.source_block_research_requirements_empty_state",
            "PortGame.source_block_research_requirements_loop_shape_state",
            "PortGame.source_block_research_requirements_quantity_formula_state",
            "PortGame.source_block_research_requirements_round_amount_state",
            "PortGame.source_block_research_requirements_output_fill_state",
        ):
            self.assertIn('"source_owner": "' + source_owner + '"', module_source)

