    def test_unit_payload_content_uses_canonical_module_constants_without_duplicate_literals(self):
        basic = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadBasicState.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadContentState.gd"
        basic_source = basic.read_text(encoding="utf-8")
        module_source = module.read_text(encoding="utf-8")

        for expected in (
            'const SOURCE_UNIT_PAYLOAD_SOURCE := "core/src/mindustry/world/blocks/payloads/UnitPayload.java"',
            'const SOURCE_UNIT_PAYLOAD_CLASS_EXPR := "public class UnitPayload implements Payload{"',
            'const SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR := "public Unit unit;"',
            'const SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR := "@Override"',
        ):
            self.assertIn(expected, basic_source)

        for expected in (
            'const SourceUnitPayloadBasicState := preload("res://src/game/SourceUnitPayloadBasicState.gd")',
            "const SOURCE_UNIT_PAYLOAD_SOURCE := SourceUnitPayloadBasicState.SOURCE_UNIT_PAYLOAD_SOURCE",
            "const SOURCE_UNIT_PAYLOAD_CLASS_EXPR := SourceUnitPayloadBasicState.SOURCE_UNIT_PAYLOAD_CLASS_EXPR",
            "const SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR := SourceUnitPayloadBasicState.SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR",
            "const SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR := SourceUnitPayloadBasicState.SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR",
            'const SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_METHOD := "public boolean contentEquals(Payload other){"',
            'const SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_RETURN_EXPR := "return other instanceof UnitPayload up && up.unit.type == unit.type;"',
            'const SOURCE_UNIT_PAYLOAD_UPDATE_METHOD := "public void update(@Nullable Unit unitHolder, @Nullable Building buildingHolder){"',
            'const SOURCE_UNIT_PAYLOAD_UPDATE_PAYLOAD_EXPR := "unit.type.updatePayload(unit, unitHolder, buildingHolder);"',
            'const SOURCE_UNIT_PAYLOAD_CONTENT_METHOD := "public UnlockableContent content(){"',
            'const SOURCE_UNIT_PAYLOAD_CONTENT_RETURN_EXPR := "return unit.type;"',
        ):
            self.assertIn(expected, module_source)

        body_expectations = {
            "content_equals_state": (
                '"source": SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_METHOD',
                '"return_expr": SOURCE_UNIT_PAYLOAD_CONTENT_EQUALS_RETURN_EXPR',
            ),
            "update_state": (
                '"source": SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_UPDATE_METHOD',
                '"update_payload_expr": SOURCE_UNIT_PAYLOAD_UPDATE_PAYLOAD_EXPR',
            ),
            "content_state": (
                '"source": SOURCE_UNIT_PAYLOAD_SOURCE',
                '"class_expr": SOURCE_UNIT_PAYLOAD_CLASS_EXPR',
                '"field_expr": SOURCE_UNIT_PAYLOAD_UNIT_FIELD_EXPR',
                '"override_expr": SOURCE_UNIT_PAYLOAD_OVERRIDE_EXPR',
                '"method": SOURCE_UNIT_PAYLOAD_CONTENT_METHOD',
                '"return_expr": SOURCE_UNIT_PAYLOAD_CONTENT_RETURN_EXPR',
            ),
        }
        duplicate_literals = (
            '"source": "core/src/mindustry/world/blocks/payloads/UnitPayload.java"',
            '"class_expr": "public class UnitPayload implements Payload{"',
            '"field_expr": "public Unit unit;"',
            '"override_expr": "@Override"',
            '"method": "public boolean contentEquals(Payload other){"',
            '"return_expr": "return other instanceof UnitPayload up && up.unit.type == unit.type;"',
            '"method": "public void update(@Nullable Unit unitHolder, @Nullable Building buildingHolder){"',
            '"update_payload_expr": "unit.type.updatePayload(unit, unitHolder, buildingHolder);"',
            '"method": "public UnlockableContent content(){"',
            '"return_expr": "return unit.type;"',
        )
        for method_name, expected_lines in body_expectations.items():
            method_body = module_source.split("static func " + method_name, 1)[1].split("\nstatic func ", 1)[0]
            for expected in expected_lines:
                self.assertIn(expected, method_body)
            for duplicate_literal in duplicate_literals:
                self.assertNotIn(duplicate_literal, method_body)

