    def test_port_game_delegates_unit_payload_draw_source_state_to_module(self):
        port_game = ROOT / "godot-mindustry" / "src" / "game" / "PortGame.gd"
        module = ROOT / "godot-mindustry" / "src" / "game" / "SourceUnitPayloadDrawState.gd"
        source = port_game.read_text(encoding="utf-8")

        self.assertTrue(module.exists(), "SourceUnitPayloadDrawState.gd must own UnitPayload draw source state")
        module_source = module.read_text(encoding="utf-8")
        self.assertIn('const SourceUnitPayloadDrawState := preload("res://src/game/SourceUnitPayloadDrawState.gd")', source)

        delegations = {
            "func source_unit_payload_draw_shadow_type_null_state(unit_type_null: bool, alpha: float, unit_id: Variant) -> Dictionary:": "\treturn SourceUnitPayloadDrawState.draw_shadow_type_null_state(unit_type_null, alpha, unit_id)",
            "func source_unit_payload_draw_type_null_state(unit_type_null: bool) -> Dictionary:": "\treturn SourceUnitPayloadDrawState.draw_type_null_state(unit_type_null)",
            "func source_unit_payload_draw_elevation_setup_state(unit_type_null: bool, unit_elevation: float, unit_id: Variant) -> Dictionary:": "\treturn SourceUnitPayloadDrawState.draw_elevation_setup_state(unit_type_null, unit_elevation, unit_id)",
            "func source_unit_payload_draw_overlay_warning_state(unit_type_null: bool, unit_elevation: float, unit_id: Variant, overlay_time: float, overlay_region: Variant, unit_x: float, unit_y: float, time_delta: float, draw_z_before: float, interp_exp5_out_overlay_time: float) -> Dictionary:": "\treturn SourceUnitPayloadDrawState.draw_overlay_warning_state(unit_type_null, unit_elevation, unit_id, overlay_time, overlay_region, unit_x, unit_y, time_delta, draw_z_before, interp_exp5_out_overlay_time)",
            "func source_unit_payload_icon_state(unit_type_full_icon: Variant) -> Dictionary:": "\treturn SourceUnitPayloadDrawState.icon_state(unit_type_full_icon)",
        }
        for signature, delegation in delegations.items():
            method_body = self._method_body(source, signature)
            self.assertIn(delegation, method_body)
            self.assertNotIn('"source": "core/src/mindustry/world/blocks/payloads/UnitPayload.java"', method_body)

        for method_name in (
            "draw_shadow_type_null_state",
            "draw_type_null_state",
            "draw_elevation_setup_state",
            "draw_overlay_warning_state",
            "icon_state",
        ):
            self.assertIn("static func " + method_name, module_source)

        for source_owner in (
            "PortGame.source_unit_payload_draw_shadow_type_null_state",
            "PortGame.source_unit_payload_draw_type_null_state",
            "PortGame.source_unit_payload_draw_elevation_setup_state",
            "PortGame.source_unit_payload_draw_overlay_warning_state",
            "PortGame.source_unit_payload_icon_state",
        ):
            self.assertIn('"source_owner": "' + source_owner + '"', module_source)

